import {bindTerrainMaterial} from './appearance.mjs';
import {makeTerrain, inside, groundAt, evalLink, linkProfile, resolveRadio, PRESETS} from './physics.mjs';
const $=id=>document.getElementById(id), base=[3500,3500],target=[4000,5500];
const stage=new URLSearchParams(location.search).get('level')==='2'?2:1, target2=[3000,5200];
if(stage===2){document.querySelector('small').textContent='LEVEL 2 / 두 개의 신호';document.querySelector('h1').textContent='두 탐사 지점을 연결하세요';document.querySelector('h1 + p').textContent='중계소 하나로 탐사 지점 A와 B의 통신 경로를 모두 확보하세요.';document.getElementById('target2').removeAttribute('hidden');}
const sites={};let selected=null,T,update3d=()=>{};
const radio=resolveRadio(PRESETS.sband);
function link(a,b,ha,hb){const out=linkProfile(T,radio,...a,ha,...b,hb,T.res);const gaps=Array.from(out.d,(d,i)=>out.zFlat[i]-(out.za+(out.zb-out.za)*d/out.D)).slice(1,-1);out.blockage=Math.max(...gaps);out.visible=Number.isFinite(out.blockage)&&out.blockage<=0;return out;}
function choosePoint(p){if(!T)return;if(!inside(T,...p)||[base,target,...(stage===2?[target2]:[])].some(q=>Math.hypot(q[0]-p[0],q[1]-p[1])<30)){ $('pick-help').textContent='고도값이 없는 곳이거나 기지·탐사 지점과 너무 가깝습니다. 다른 위치를 선택하세요.';return;}const paths=[[base,p,4,3],[p,target,3,2],...(stage===2?[[p,target2,3,2]]:[])];if(paths.some(([a,b,h1,h2])=>{const v=linkProfile(T,radio,...a,h1,...b,h2,T.res);return ![...v.zFlat].every(Number.isFinite)})){ $('pick-help').textContent='경로의 일부에 지형 자료가 없습니다. 다른 위치를 선택하세요.';return;}sites['선택 지점']=p;selected='선택 지점';if(window.parent!==window)window.parent.postMessage({type:'level-result',level:stage,success:false},location.origin);$('pick-help').textContent=`선택 위치: 동쪽 ${Math.round(p[0])}m, 남쪽 ${Math.round(p[1])}m. 아래 단면을 확인하고 설치하세요.`;$('check').disabled=false;$('result').hidden=true;$('lines').innerHTML='';paint();preview();update3d(false);}
if(stage===2){
 $('pick-help').textContent='지도에서 기지와 탐사 A·B를 살펴보세요. 지점을 누르면 설치 전에 세 구간의 단면과 연결 조건을 확인할 수 있습니다.';
 $('hint').innerHTML=`<summary>단계별 탐색 힌트</summary>
 <details><summary>힌트 1 · 어디를 살펴볼까?</summary><p>기지에서 신호를 받아 탐사 A와 B 양쪽에 전달해야 합니다. 지도에서 세 지점 사이의 능선과 높은 지형을 살펴보세요. 높다고 항상 유리한 것은 아니니 주변도 비교해 보세요.</p></details>
 <details><summary>힌트 2 · 선택한 지점은 어떻게 판단할까?</summary><p>지점을 누르면 설치 전에 세 경로가 표시됩니다. 주황색 지형이 초록 직선보다 위에 있으면 가로막힌 구간입니다. 세 경로 모두 가시선이 확보되고 신호 여유가 3 dB 이상이어야 성공합니다.</p></details>
 <details><summary>힌트 3 · 연결이 안 될 때는?</summary><p>설치 전 조사에서 기준 미달 구간을 확인한 뒤, 그 구간의 능선을 피하거나 다른 지점에서 다시 조사해 보세요. 지도를 클릭하는 것만으로는 중계소가 설치되지 않습니다.</p></details>`;
}
$('terrain2d').addEventListener('click',event=>{const svg=$('terrain2d'),pt=svg.createSVGPoint();pt.x=event.clientX;pt.y=event.clientY;const p=pt.matrixTransform(svg.getScreenCTM().inverse());choosePoint([p.x,p.y]);});
function paint(){ $('points').innerHTML=Object.entries(sites).map(([id,[x,y]])=>`<circle cx="${x}" cy="${y}" r="80" fill="${selected===id?'#f4ac78':'#323c2e'}" stroke="#f4ac78" stroke-width="16"/><text x="${x+95}" y="${y}" fill="white" font-size="100">${id}</text>`).join(''); }
for(const id of Object.keys(sites)){const b=document.createElement('button');b.className='candidate';b.textContent=`후보지 ${id}`;b.onclick=()=>{selected=id;if(window.parent!==window)window.parent.postMessage({type:'level-result',level:stage,success:false},location.origin);document.querySelectorAll('.candidate').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('check').disabled=!T;$('result').hidden=true;$('lines').innerHTML='';paint();preview();update3d(false);};$('buttons').append(b);}
$('reset').onclick=()=>{if(window.parent!==window)window.parent.postMessage({type:'level-result',level:stage,success:false},location.origin);selected=null;delete sites['선택 지점'];$('pick-help').textContent='지도에서 중계소를 놓을 위치를 클릭하세요.';$('preview').hidden=true;$('check').disabled=true;$('result').hidden=true;$('lines').innerHTML='';document.querySelectorAll('.candidate').forEach(b=>b.setAttribute('aria-pressed','false'));paint();update3d(false);};
function profile(title,p,q,h1,h2){const v=linkProfile(T,radio,...p,h1,...q,h2,T.res);const z=[...v.zFlat,v.za,v.zb].filter(Number.isFinite),lo=Math.min(...z)-5,hi=Math.max(...z)+5;const x=d=>40+620*d/v.D,y=h=>170-140*(h-lo)/(hi-lo);const pts=[...v.d].map((d,i)=>Number.isFinite(v.zFlat[i])?`${x(d)},${y(v.zFlat[i])}`:'').filter(Boolean).join(' ');return `<article class="profile-card"><h3>${title}</h3><svg viewBox="0 0 700 205" role="img" aria-label="${title} 지형 단면"><polyline points="${pts}" fill="none" stroke="#f4ac78" stroke-width="3"/><line x1="40" y1="${y(v.za)}" x2="660" y2="${y(v.zb)}" stroke="#8cd7b0" stroke-width="2"/></svg><p>주황: 지형 단면 · 초록: 안테나 사이 직선</p></article>`;}
function preview(){if(!T||!selected)return;const p=sites[selected];const paths=[[`기지 → 조사 지점`,base,p,4,3],[`조사 지점 → 탐사 A`,p,target,3,2],...(stage===2?[[`조사 지점 → 탐사 B`,p,target2,3,2]]:[])];const assessment=paths.map(([name,a,b,ha,hb])=>{const v=link(a,b,ha,hb),valid=Number.isFinite(v.blockage)&&Number.isFinite(v.margin);return `<li><strong>${name}:</strong> ${valid?`가시선 ${v.visible?'확보':'가림'} · 신호 여유 ${v.margin.toFixed(1)} dB · ${v.visible&&v.margin>=3?'기준 충족':'기준 미달'}`:'자료 부족'}</li>`}).join('');$('preview').hidden=false;$('preview').innerHTML=`<h2>후보지 ${selected} 사전 조사</h2><p>고도 약 ${Math.round(groundAt(T,...p))}m · 주황 지형과 초록 직선을 비교해 지형이 가로막는지 살펴보세요. 고도는 화성 기준면을 기준으로 합니다.</p><p><strong>설치 전 연결 조사</strong> · 각 구간에서 가시선 확보와 신호 여유 3 dB 이상이 필요합니다.</p><ul>${assessment}</ul>${profile(`기지 → 후보지 ${selected}`,base,p,4,3)}${profile(`후보지 ${selected} → 탐사 A`,p,target,3,2)}${stage===2?profile(`후보지 ${selected} → 탐사 B`,p,target2,3,2):''}`;}
$('check').onclick=()=>{const a=link(base,sites[selected],4,3),b=link(sites[selected],target,3,2),c=stage===2?link(sites[selected],target2,3,2):null,segments=[a,b,...(c?[c]:[])],ok=segments.every(v=>v.visible&&v.margin>=3);$('lines').innerHTML=[[base,sites[selected],a],[sites[selected],target,b],...(c?[[sites[selected],target2,c]]:[])].map(([p,q,v])=>`<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="${v.visible&&v.margin>=3?'#8cd7b0':'#ff876c'}" stroke-width="20"/>`).join('');update3d(true);if(window.parent!==window)window.parent.postMessage({type:'level-result',level:stage,success:ok},location.origin);$('result').hidden=false;$('result').innerHTML=`<h2>${ok?'통신 경로 복구 성공':'통신 경로 확보 실패'}</h2><p>${ok?'모든 구간의 가시선과 계산상 신호 여유가 확보되었습니다.':'하나 이상의 구간에서 가시선이 가려지거나 신호 여유가 부족합니다. 구간별 결과를 확인하고 다른 후보지를 선택해 보세요.'}</p><ul>${[[`기지 → ${selected}`,a],[`${selected} → 탐사 A`,b],...(c?[[`${selected} → 탐사 B`,c]]:[])].map(([name,v])=>`<li>${name}: 가시선 ${v.visible?'확보':'지형에 가림'} · 신호 ${v.margin>=3?'계산상 가능':'계산상 부족'} (${v.margin.toFixed(1)} dB)</li>`).join('')}</ul><p>가시선이 막혀도 전파 회절로 신호가 도달할 수 있습니다. 이 미션은 모든 구간의 가시선 확보와 3 dB 이상의 신호 여유를 모두 요구합니다. 실제 통신 성능을 보장하지 않습니다.</p><p>설치 전 조사에서 확인한 지형 단면은 위에 그대로 남아 있습니다.</p>`;};
try{const [m,buf]=await Promise.all([fetch('./data/meta.json').then(r=>{if(!r.ok)throw Error('metadata');return r.json()}),fetch('./data/terrain_8m.f32').then(r=>{if(!r.ok)throw Error('terrain');return r.arrayBuffer()})]);T=makeTerrain(buf,m);if(![base,target,...(stage===2?[target2]:[]),...Object.values(sites)].every(p=>inside(T,...p)))throw Error('범위 밖 위치');paint();if(selected)preview();init3d(T).catch(()=>{$('terrain3d').textContent='3D 지형을 불러오지 못했습니다. 아래 2D 지도와 단면을 이용해 주세요.';});}catch(e){$('result').hidden=false;$('result').textContent='지형 자료를 불러오지 못했습니다. 로컬 웹 서버에서 열어 주세요.';}

async function init3d(T){
 const THREE=await import('https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js');
 const {OrbitControls}=await import('https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js');
 const el=$('terrain3d'),w=el.clientWidth||600,h=330,renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));renderer.setSize(w,h);el.replaceChildren(renderer.domElement);
 const scene=new THREE.Scene();scene.background=new THREE.Color(0x161c19);const camera=new THREE.PerspectiveCamera(42,w/h,1,20000);camera.position.set(1800,2100,2300);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,0,0);controls.enableDamping=true;controls.update();scene.add(new THREE.HemisphereLight(0xffffff,0x493224,2));const light=new THREE.DirectionalLight(0xffffff,1.4);light.position.set(-1000,3000,-1200);scene.add(light);
 const x0=2000,y0=3000,sx=2500,sy=3000,n=100,vertices=[],uv=[],indices=[];let center=groundAt(T,3250,4500);for(let j=0;j<=n;j++)for(let i=0;i<=n;i++){let x=x0+sx*i/n,y=y0+sy*j/n,z=groundAt(T,x,y);vertices.push(x-3250,(Number.isFinite(z)?z-center:0)*2,y-4500);uv.push(x/(T.w*T.res),1-y/(T.h*T.res));if(i<n&&j<n){let k=j*(n+1)+i;indices.push(k,k+n+1,k+1,k+1,k+n+1,k+n+2);}}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));geometry.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geometry.setIndex(indices);geometry.computeVertexNormals();const texture=await new THREE.TextureLoader().loadAsync('./data/ortho_4m.jpg');texture.colorSpace=THREE.SRGBColorSpace;const terrainMaterial=new THREE.MeshStandardMaterial({map:texture,side:THREE.DoubleSide});bindTerrainMaterial(terrainMaterial);const terrainMesh=new THREE.Mesh(geometry,terrainMaterial);scene.add(terrainMesh);{const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let down=null;renderer.domElement.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY]});renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const rect=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObject(terrainMesh)[0];if(hit)choosePoint([hit.point.x+3250,hit.point.z+4500]);});}
 const positions={기지:base,'탐사 A':target,...(stage===2?{'탐사 B':target2}:{})};
 const markers={};const point3=(p,height=0)=>new THREE.Vector3(p[0]-3250,(groundAt(T,...p)+height-center)*2,p[1]-4500);
 function label(text){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=128;const c=canvas.getContext('2d');c.fillStyle='rgba(12,20,16,.88)';c.fillRect(0,5,512,118);c.font='bold 54px sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillStyle='white';c.fillText(text,256,65);const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(canvas),depthTest:false,transparent:true}));sprite.scale.set(430,108,1);sprite.renderOrder=10;return sprite;}
 for(const [id,p] of Object.entries(positions)){const marker=new THREE.Mesh(new THREE.SphereGeometry(35,16,12),new THREE.MeshBasicMaterial({color:id==='기지'?0xffffff:id==='탐사 A'?0xff8262:id==='탐사 B'?0xcaaaff:0xf4ac78,depthTest:false}));marker.position.copy(point3(p,25));marker.renderOrder=9;scene.add(marker);const tag=label(['A','B','C'].includes(id)?`후보지 ${id}`:id);tag.position.copy(point3(p,110));scene.add(tag);markers[id]=marker;}
 const routes=new THREE.Group();scene.add(routes);update3d=(confirmed=false)=>{while(routes.children.length){const obj=routes.children[0];routes.remove(obj);obj.geometry.dispose();obj.material.dispose();}for(const id of ['A','B','C'])if(markers[id])markers[id].scale.setScalar(id===selected?1.55:1);if(selected){const p=sites[selected],marker=new THREE.Mesh(new THREE.SphereGeometry(40,16,12),new THREE.MeshBasicMaterial({color:0xf4ac78,depthTest:false}));marker.position.copy(point3(p,25));marker.renderOrder=9;routes.add(marker);}if(!selected)return;const legs=[[base,sites[selected],4,3],[sites[selected],target,3,2],...(stage===2?[[sites[selected],target2,3,2]]:[])];for(const [a,b,h1,h2] of legs){const v=confirmed?link(a,b,h1,h2):null;const color=confirmed?(v.visible&&v.margin>=3?0x8cd7b0:0xff876c):0xffd166;const geo=new THREE.BufferGeometry().setFromPoints([point3(a,h1),point3(b,h2)]);const line=new THREE.Line(geo,new THREE.LineDashedMaterial({color,dashSize:60,gapSize:35,depthTest:false}));line.computeLineDistances();line.renderOrder=8;routes.add(line);}};update3d(false);
 const resize=new ResizeObserver(()=>{let w=el.clientWidth;if(!w)return;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()});resize.observe(el);function animate(){controls.update();renderer.render(scene,camera);requestAnimationFrame(animate)}animate();
}
